#include "ui/MaterialPanel.hpp"
#include <imgui.h>
namespace scene_editor {void drawMaterialPanel(Scene& scene){if(auto* object=scene.find(scene.selectedId)){ImGui::SeparatorText("材质");bool changed=false;changed|=ImGui::ColorEdit3("基础颜色",&object->material.color.x);changed|=ImGui::ColorEdit3("环境光",&object->material.ambient.x);changed|=ImGui::ColorEdit3("漫反射",&object->material.diffuse.x);changed|=ImGui::ColorEdit3("高光",&object->material.specular.x);changed|=ImGui::SliderFloat("光泽度",&object->material.shininess,1.0F,256.0F);changed|=ImGui::ColorEdit3("自发光颜色",&object->material.emission.x);changed|=ImGui::SliderFloat("自发光强度",&object->material.emissionStrength,0.0F,10.0F);ImGui::TextDisabled("自发光使物体可见；照亮周围仍需添加点光源。");static char path[512]{};static std::string selectedId;if(selectedId!=object->id){selectedId=object->id;snprintf(path,sizeof(path),"%s",object->material.texturePath.c_str());}ImGui::TextDisabled("漫反射纹理文件（可选）");ImGui::SetNextItemWidth(-1);if(ImGui::InputText("##TexturePath",path,sizeof(path))){object->material.texturePath=path;changed=true;}if(changed)object->materialOverride=true;}else ImGui::TextUnformatted("请先选择对象。 ");}}
